"1312 :     public static boolean isNumber(String str) {
1313 :         if (StringUtils.isEmpty(str)) {
1314 :             return false;
1315 :         }
1316 :         char[] chars = str.toCharArray();
1317 :         int sz = chars.length;
1318 :         boolean hasExp = false;
1319 :         boolean hasDecPoint = false;
1320 :         boolean allowSigns = false;
1321 :         boolean foundDigit = false;
1322 :         // deal with any possible sign up front
1323 :         int start = (chars[0] == '-') ? 1 : 0;
1324 :         if (sz > start + 1) {
1325 :             if (chars[start] == '0' && chars[start + 1] == 'x') {
1326 :                 int i = start + 2;
1327 :                 if (i == sz) {
1328 :                     return false; // str == "0x"
1329 :                 }
1330 :                 // checking hex (it can't be anything else)
1331 :                 for (; i < chars.length; i++) {
1332 :                     if ((chars[i] < '0' || chars[i] > '9')
1333 :                         && (chars[i] < 'a' || chars[i] > 'f')
1334 :                         && (chars[i] < 'A' || chars[i] > 'F')) {
1335 :                         return false;
1336 :                     }
1337 :                 }
1338 :                 return true;
1339 :             }
1340 :         }
1341 :         sz--; // don't want to loop to the last char, check it afterwords
1342 :               // for type qualifiers
1343 :         int i = start;
1344 :         // loop to the next to last char or to the last char if we need another digit to
1345 :         // make a valid number (e.g. chars[0..5] = "1234E")
1346 :         while (i < sz || (i < sz + 1 && allowSigns && !foundDigit)) {
1347 :             if (chars[i] >= '0' && chars[i] <= '9') {
1348 :                 foundDigit = true;
1349 :                 allowSigns = false;
1350 : 
1351 :             } else if (chars[i] == '.') {
1352 :                 if (hasDecPoint || hasExp) {
1353 :                     // two decimal points or dec in exponent   
1354 :                     return false;
1355 :                 }
1356 :                 hasDecPoint = true;
1357 :             } else if (chars[i] == 'e' || chars[i] == 'E') {
1358 :                 // we've already taken care of hex.
1359 :                 if (hasExp) {
1360 :                     // two E's
1361 :                     return false;
1362 :                 }
1363 :                 if (!foundDigit) {
1364 :                     return false;
1365 :                 }
1366 :                 hasExp = true;
1367 :                 allowSigns = true;
1368 :             } else if (chars[i] == '+' || chars[i] == '-') {
1369 :                 if (!allowSigns) {
1370 :                     return false;
1371 :                 }
1372 :                 allowSigns = false;
1373 :                 foundDigit = false; // we need a digit after the E
1374 :             } else {
1375 :                 return false;
1376 :             }
1377 :             i++;
1378 :         }
1379 :         if (i < chars.length) {
1380 :             if (chars[i] >= '0' && chars[i] <= '9') {
1381 :                 // no type qualifier, OK
1382 :                 return true;
1383 :             }
1384 :             if (chars[i] == 'e' || chars[i] == 'E') {
1385 :                 // can't have an E at the last byte
1386 :                 return false;
1387 :             }
1388 :             if (!allowSigns
1389 :                 && (chars[i] == 'd'
1390 :                     || chars[i] == 'D'
1391 :                     || chars[i] == 'f'
1392 :                     || chars[i] == 'F')) {
1393 :                 return foundDigit;
1394 :             }
1395 :             if (chars[i] == 'l'
1396 :                 || chars[i] == 'L') {
1397 :                 // not allowing L with an exponent
1398 :                 return foundDigit && !hasExp;
1399 :             }
1400 :             // last character is illegal
1401 :             return false;
1402 :         }
1403 :         // allowSigns is true iff the val ends in 'E'
1404 :         // found digit it to make sure weird stuff like '.' and '1E-' doesn't pass
1405 :         return !allowSigns && foundDigit;
1406 :     }"

